import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-067","description":"","frontmatter":{"date":"2020-09-24T22:07:40","title":"写作课作业-067","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"思考","slug":"思考","link":"#思考","children":[]}],"relativePath":"posts/homework/067.md","filePath":"posts/homework/067.md"}'),l={name:"posts/homework/067.md"};function s(p,e,i,n,c,_){return a(),o("div",null,[...e[0]||(e[0]=[r('<blockquote><p>9.24写作作业：读《微信互联网平民创业》之《小序》，读书笔记的模（可以在此基础上，资源发挥）： 1.总结书中知识要点： 2.我对知识点的思考： 3.书中精彩的例子，可以用在其他什么地方： 4.书中用了排比、递进、转折吗？ 5.哪些知识点可以运用到自己学习、生活和工作中</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><p>从写“如何让自己更值钱”到写“如何赚钱”。李笑来给自己定了一条铁律：李笑来只写自己已经做到的事。想到、学到都不算数，必须做到才值得分享，才有资格分享......，成为“有资格说那话、有资格讲那事的人”。</p><p>真正的困难的是:能不能一直赚钱?与此同时，有没有可能越赚越多?</p><p>李笑 来能够让相当数量的平⺠(比如 1,000 位，10,000 位?)变成「平⺠头部」(简称「平 头」哈哈)，那应该是多么令人高兴、多么令人激动的结果呢?</p><h2 id="思考" tabindex="-1">思考 <a class="header-anchor" href="#思考" aria-label="Permalink to &quot;思考&quot;">​</a></h2><p>给自己设定原则，甚至是铁律很重要，如果这个原则的标准越高，自己都做到了，自己就越可能成为一个猛人。</p><p>赚钱是一个可以敞开说的事情，但需要不断成长，加强自己的赚钱能力，长期赚钱的能力。</p><p>帮助别人成功，是令人快乐的，同时也是服务的本质。对于自己来说，需要持续思考自己能通过什么方式服务好1000个人。</p>',9)])])}const m=t(l,[["render",s]]);export{h as __pageData,m as default};
